-- python -m dip contracts dbt finance.purchase_orders --write
{{ config(schema='silver', materialized='view', tags=['file_feed', 'finance.purchase_orders', 'generated']) }}

-- Silver: every accepted row of every finance.purchase_orders file, typed by the contract.
with deliveries as (
    select distinct on (d.file_sha256)
        d.file_sha256,
        d.source_key,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) as file_date,
        d.received_at
    from {{ source('ops', 'intake_delivery') }} as d
    where d.feed = 'finance.purchase_orders'
    order by
        d.file_sha256,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) desc,
        d.received_at desc,
        d.source_key desc
)

select
    b.file_sha256,
    b.row_number,
    d.source_key,
    d.file_date,
    d.received_at,
    f.contract_version,
    b.record ->> 'po_number' as "po_number",
    (b.record ->> 'line')::bigint as "line",
    b.record ->> 'vendor_id' as "vendor_id",
    (b.record ->> 'order_date')::date as "order_date",
    (b.record ->> 'amount')::numeric as "amount",
    b.record ->> 'currency' as "currency",
    (b.record ->> 'approved')::boolean as "approved",
    nullif(b.record ->> 'note', '') as "note",
    (nullif(b.record ->> 'due_date', ''))::date as "due_date"
from {{ source('bronze', 'csv_record') }} as b
inner join {{ source('ops', 'intake_file') }} as f
    on f.feed = b.feed and f.file_sha256 = b.file_sha256
inner join deliveries as d on d.file_sha256 = b.file_sha256
where b.feed = 'finance.purchase_orders'
